import json

def diff_tree(a, b):
    def _traverse(node, path):
        if isinstance(node, dict):
            result = {}
            for k, v in node.items():
                new_path = f"{path}.{k}" if path else k
                result.update(_traverse(v, new_path))
            return result
        else:
            return {path: [node, node] if path else [node, node]}

    result_a = _traverse(a, "")
    result_b = _traverse(b, "")
    diff = {}

    for key in set(result_a.keys()).union(set(result_b.keys())):
        if key in result_a and key in result_b:
            if result_a[key] != result_b[key]:
                diff[key] = result_a[key]
        elif key in result_a:
            diff[key] = result_a[key]
        elif key in result_b:
            diff[key] = result_b[key]

    return diff

def _rel():
    import json

    def check_output(a, b, expected):
        actual = diff_tree(a, b)
        if json.dumps(actual, ensure_ascii=False) == json.dumps(expected, ensure_ascii=False):
            return True
        else:
            raise AssertionError(f"Expected {expected}, but got {actual}")

    # 自选输入
    check_output(
        {"a": 1, "b": {"c": 2, "d": 3}, "e": 4},
        {"a": 1, "b": {"c": 2, "d": 4}, "e": 4},
        {"b.d": [3, 4]}
    )

    check_output(
        {"x": {"y": {"z": 1}}}, 
        {"x": {"y": {"z": 2}}}, 
        {"x.y.z": [1, 2]}
    )

    check_output(
        {"a": 1, "b": 2}, 
        {"a": 1, "b": 2}, 
        {}
    )

    check_output(
        {"a": 1, "b": 2}, 
        {}, 
        {"a": [1, None], "b": [2, None]}
    )

    check_output(
        {}, 
        {"a": 1, "b": 2}, 
        {"a": [None, 1], "b": [None, 2]}
    )

    check_output(
        {"a": 1, "b": 2}, 
        {"a": 1, "b": 3, "c": 4}, 
        {"b": [2, 3]}
    )

    _rel()

