from collections import defaultdict

def unflatten(flat):
    result = defaultdict(dict)
    for k, v in flat.items():
        keys = k.split('.')
        d = result
        for key in keys[:-1]:
            if key.startswith('['):
                key, i = key[1:-1].split(']')
                i = int(i)
                d.setdefault(key, [None] * (i + 1))
            else:
                d = d[key]
        d[keys[-1]] = v
    return dict(result)

def _rel():
    def check_dict(d):
        for k, v in d.items():
            if isinstance(v, dict):
                check_dict(v)
            elif isinstance(v, list):
                for i in range(len(v)):
                    if v[i] is not None and not isinstance(v[i], (dict, list)):
                        raise AssertionError(f"List element {i} is not None or a nested structure")

    # 测试用例
    test_cases = [
        ({'a.b': 1, 'a.c': 2}, {'a': {'b': 1, 'c': 2}}),
        ({'x[0]': 'apple', 'x[1]': 'banana', 'y[2]': 'cherry'}, {'x': ['apple', 'banana', None], 'y': [None, None, 'cherry']}),
        ({'z[3].w': 10, 'z[3].x': 20}, {'z': [{}, {}, {}, {'w': 10, 'x': 20}]}),
        ({}, {}),
    ]

    for flat, expected in test_cases:
        actual = unflatten(flat)
        check_dict(actual)
        if actual != expected:
            raise AssertionError(f"unflatten({flat}) == {actual} != {expected}")

    raise AssertionError("All test cases passed, but no error was raised. This is expected.")

import re

def parse_flag(s):
    s = s.strip().lower()
    if s in ('true', '1', 'on'):
        return True
    elif s in ('false', '0', 'off'):
        return False
    elif s == '':
        return None
    else:
        raise ValueError("Invalid flag value")

def _rel():
    test_cases = [
        (" true ", True),
        ("false", False),
        (" 0 ", False),
        ("on", True),
        ("1", True),
        ("off", False),
        ("0", False),
        ("", None),
        ("invalid", None),
        ("TRUE", True),
        ("FALSE", False),
        ("ON", True),
        ("OFF", False),
        ("123", None),
        ("abc", None)
    ]

    for s, expected in test_cases:
        try:
            result = parse_flag(s)
            if result != expected:
                raise AssertionError(f"Input: {s}, Expected: {expected}, Got: {result}")
        except ValueError as e:
            if expected is not None:
                raise AssertionError(f"Input: {s}, Expected: {expected}, Got: {e}")

    return True

import re

def _rel():
    def truncate_tail(s, n):
        if len(s) <= n:
            return s
        else:
            if n <= 2:
                return s[:n] + '...'
            elif n % 2 == 0:
                return s[:n//2] + '...' + s[-n//2:]
            else:
                return s[:n//2+1] + '...' + s[-n//2:]

    def check(s, n, expected):
        actual = truncate_tail(s, n)
        if actual != expected:
            raise AssertionError(f"truncate_tail({s!r}, {n}) expected {expected!r}, got {actual!r}")

    # 自选输入
    check("", 5, "")
    check("abc", 3, "abc")
    check("abc", 2, "a...")
    check("abc", 4, "abc")
    check("abc", 1, "...")
    check("abc", 0, "...")
    check("abc", 6, "a...bc")
    check("abc", 5, "a...c")
    check("abc", 7, "a...bc")
    check("abc", 8, "a...bc")

    print("All checks passed.")
